rules_version = '2';

service cloud.firestore {
  match /databases/{database}/documents {
    // Allow authenticated user to read/write their own user document
    match /users/{userId} {
      allow read, write: if request.auth != null && request.auth.uid == userId;
    }

    // Allow authenticated user to read/write any subcollection under their user document
    match /users/{userId}/{document=**} {
      allow read, write: if request.auth != null && request.auth.uid == userId;
    }
  }
}
